import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import {
  getClientEntitlements,
  getEffectivePlan,
  hasUnresolvedBillingPeriod,
  EntitlementError,
} from "@/lib/entitlements";
import { requireTemplateAccess } from "@/lib/template-policy";
import { AppError } from "@/lib/errors";
import { cancelQueuedIn } from "@/lib/cancellation";

// Owner lock is required. The immutable send snapshots describe the original
// campaign, including its completed and cancelled recipients.
export async function cancelIneligibleCampaign(
  tx: Prisma.TransactionClient,
  userId: string,
  campaignId: string,
  now = new Date(Date.now()),
) {
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  const control = await tx.systemControl.findUnique({
    where: { key: "global" },
  });
  const access = getClientEntitlements(user, control, now);
  if (
    !access.paidGatingEnabled ||
    !access.features.templateUse ||
    hasUnresolvedBillingPeriod(user, now)
  )
    return false;
  const campaign = await tx.campaign.findFirst({
    where: { id: campaignId, userId },
    include: {
      sends: {
        select: { id: true, recipientRole: true, recipientEmail: true },
      },
    },
  });
  if (!campaign) return true;
  let reason: string | null = null;
  let reasonCode = "FREE_FEATURE";
  if (
    Math.max(campaign.approvedRecipientCount, campaign.sends.length) >
    access.limits.campaignRecipients
  ) {
    reason = `This campaign exceeds your current ${access.limits.campaignRecipients}-recipient limit.`;
    reasonCode = "FREE_RECIPIENT_LIMIT";
  }
  if (!reason) {
    try {
      if (!campaign.templateId)
        throw new AppError("The campaign template is unavailable.");
      await requireTemplateAccess(tx, userId, campaign.templateId);
    } catch (error) {
      if (!(error instanceof AppError)) throw error;
      reasonCode = "FREE_TEMPLATE";
      reason =
        error instanceof EntitlementError
          ? "This campaign requires a template outside your current plan."
          : error.message;
    }
  }
  // Approved role snapshots remain usable after downgrade or contact removal.
  // New role titles are checked atomically when the campaign is submitted.
  if (!reason) return false;
  await cancelCampaignWithNotice(
    tx,
    userId,
    campaignId,
    reasonCode,
    reason,
    now,
  );
  return true;
}

export async function cancelCampaignWithNotice(
  tx: Prisma.TransactionClient,
  userId: string,
  campaignId: string,
  reasonCode: string,
  reason: string,
  now = new Date(Date.now()),
) {
  const ready = await tx.send.findMany({
    where: {
      campaignId,
      campaign: { userId },
      status: "QUEUED",
      deliveryState: "READY",
      attemptedAt: null,
    },
    select: { id: true },
  });
  const result = await cancelQueuedIn(tx, userId, { campaignId });
  if (!result.cancelled) return;
  await tx.send.updateMany({
    where: {
      id: { in: ready.map((s) => s.id) },
      campaign: { userId },
      status: "CANCELLED",
    },
    data: { error: `Cancelled: ${reason}` },
  });
  await tx.accountNotice.upsert({
    where: {
      userId_deduplicationKey: {
        userId,
        deduplicationKey: `downgrade:${campaignId}`,
      },
    },
    create: {
      userId,
      deduplicationKey: `downgrade:${campaignId}`,
      campaignIdSnapshot: campaignId,
      reasonCode,
      cancelledCount: result.cancelled,
      createdAt: now,
    },
    update: {},
  });
}

import { resolveUsagePeriods } from "@/lib/usage-periods";
import {
  ensureUsagePeriods,
  requireUsageReady,
  rebindReadyRemainder,
  type UsageOwnerTransaction,
} from "@/lib/usage-ledger";

/** One owner lock covers the complete allocation, notices and cancellation.
 * Delayed READY work competes too; attempted/uncertain evidence is never released. */
export async function applyFreeCampaignPolicy(
  owner: UsageOwnerTransaction,
  now = new Date(Date.now()),
) {
  const { tx, userId } = owner;
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  const control = await tx.systemControl.findUnique({
    where: { key: "global" },
  });
  if (
    !control?.paidGatingEnabled ||
    user.deletionRequestedAt ||
    user.isSuspended ||
    getEffectivePlan(user, now) !== "FREE" ||
    hasUnresolvedBillingPeriod(user, now)
  )
    return;
  // Whole-campaign allocation is a downgrade effect. Ordinary Free renewal
  // boundaries continue to use the existing reservation/deferral policy.
  if (
    !user.dodoSubscriptionId &&
    !user.planOverride &&
    !user.grandfatheredUntil
  )
    return;
  const campaigns = await tx.campaign.findMany({
    where: {
      userId,
      sends: {
        some: { status: "QUEUED", deliveryState: "READY", attemptedAt: null },
      },
    },
    orderBy: [{ createdAt: "asc" }, { id: "asc" }],
  });
  if (!campaigns.length) return;
  await requireUsageReady(owner, true, now);
  const specs = resolveUsagePeriods(user, now);
  const buckets = await ensureUsagePeriods(owner, specs);
  const ready = await tx.usageReservation.findMany({
    where: {
      userId,
      status: "RESERVED",
      chargedAt: null,
      send: {
        status: "QUEUED",
        deliveryState: "READY",
        attemptedAt: null,
        sentAt: null,
        gmailMessageId: null,
        campaign: { userId },
      },
    },
    include: { send: { select: { campaignId: true } } },
  });
  let daily =
    buckets.daily.sent +
    buckets.daily.reserved -
    ready.filter((r) => r.dailyPeriodId === buckets.daily.id).length;
  let monthly =
    buckets.monthly.sent +
    buckets.monthly.reserved -
    ready.filter((r) => r.monthlyPeriodId === buckets.monthly.id).length;
  for (const campaign of campaigns) {
    if (await cancelIneligibleCampaign(tx, userId, campaign.id, now)) continue;
    const remainder = ready.filter((r) => r.send?.campaignId === campaign.id);
    if (
      daily + remainder.length > specs.daily.limit ||
      monthly + remainder.length > specs.monthly.limit
    ) {
      await cancelCampaignWithNotice(
        tx,
        userId,
        campaign.id,
        "FREE_ALLOWANCE",
        "The complete unsent remainder exceeds your current Free allowance.",
        now,
      );
      continue;
    }
    await rebindReadyRemainder(
      owner,
      remainder.map((r) => r.deliveryKey),
      specs,
    );
    daily += remainder.length;
    monthly += remainder.length;
  }
}
